#ifndef C2C_AMR_ORACLE_H
#define C2C_AMR_ORACLE_H
#include "c2c_acceptance_support.h"
namespace c2c {
// Public-data reference oracle derived only from Essence 8.3/8.4. Leaf identity
// is symbolic (root, depth, dyadic index); no production mesh helpers are used.
struct Leaf {double left,right;std::size_t root,depth,index;};
struct ReferenceResult {std::vector<double> x,u;std::vector<PDE::AMREvent> events;bool limited=false;};
inline std::vector<double> indicators(std::vector<double> const& x,std::vector<double> const& u){std::size_t m=x.size();std::vector<double> h(m-1),s(m-1),C(m),I(m-1);for(std::size_t i=0;i+1<m;++i){h[i]=sub(x[i+1],x[i]);if(h[i]<=0)throw std::runtime_error("oracle indicator spacing");double du=sub(u[i+1],u[i]);s[i]=div(du,h[i]);}for(std::size_t i=1;i+1<m;++i){double jump=sub(s[i],s[i-1]);double mag=checked(std::abs(jump));double spacing=checked(std::min(h[i-1],h[i]));double half=div(spacing,2);C[i]=mul(half,mag);}C[0]=checked(C[1]);C[m-1]=checked(C[m-2]);for(std::size_t i=0;i+1<m;++i)I[i]=checked(std::max(C[i],C[i+1]));return I;}
inline double midpoint(double left,double right){double width=sub(right,left);if(width<=0)throw std::runtime_error("oracle midpoint");double half=div(width,2),mid=add(left,half);if(!(left<mid&&mid<right))throw std::runtime_error("oracle midpoint");return mid;}
inline double transfer(double left,double right,double mid,double ul,double ur){double width=sub(right,left),offset=sub(mid,left),alpha=div(offset,width),beta=sub(1,alpha),pl=mul(beta,ul),pr=mul(alpha,ur);return add(pl,pr);}
template<class P> inline void adapt(ReferenceResult& r,std::vector<Leaf>& cells,P const& p,PDE::AMROptions const& o,std::size_t step,double time){
 auto I=indicators(r.x,r.u);std::vector<bool> split(cells.size(),false);std::vector<double> mids(cells.size());std::size_t count=0;for(std::size_t i=0;i<cells.size();++i)if(I[i]>o.refine_tolerance){if(cells[i].depth==o.max_refinement_level)r.limited=true;else{split[i]=true;++count;}}
 for(std::size_t i=0;i<cells.size();++i)if(split[i])mids[i]=midpoint(cells[i].left,cells[i].right);
 bool blocked=count>o.max_nodes-r.x.size();if(blocked)r.limited=true;
 std::vector<bool> fresh;
 if(!blocked&&count){std::vector<Leaf> next;std::vector<double> x{r.x[0]},u{r.u[0]};for(std::size_t i=0;i<cells.size();++i){auto c=cells[i];if(split[i]){double mid=mids[i];double inserted=step==0?checked(p.initial(time,mid)):transfer(c.left,c.right,mid,r.u[i],r.u[i+1]);next.push_back({c.left,mid,c.root,c.depth+1,2*c.index});next.push_back({mid,c.right,c.root,c.depth+1,2*c.index+1});fresh.push_back(true);fresh.push_back(true);x.push_back(mid);u.push_back(inserted);r.events.push_back({step,time,PDE::AMRAction::refine,c.left,c.right});}else{next.push_back(c);fresh.push_back(false);}x.push_back(r.x[i+1]);u.push_back(r.u[i+1]);}cells=std::move(next);r.x=std::move(x);r.u=std::move(u);}else fresh.assign(cells.size(),false);
 I=indicators(r.x,r.u);std::vector<Leaf> next;std::vector<double> x{r.x[0]},u{r.u[0]};for(std::size_t i=0;i<cells.size();){bool merge=false;if(i+1<cells.size()){auto a=cells[i],b=cells[i+1];merge=a.depth>0&&a.depth==b.depth&&a.root==b.root&&a.index%2==0&&b.index==a.index+1&&!fresh[i]&&!fresh[i+1]&&I[i]<o.coarsen_tolerance&&I[i+1]<o.coarsen_tolerance;}if(merge){auto a=cells[i],b=cells[i+1];next.push_back({a.left,b.right,a.root,a.depth-1,a.index/2});r.events.push_back({step,time,PDE::AMRAction::coarsen,a.left,b.right});i+=2;}else{next.push_back(cells[i]);++i;}x.push_back(r.x[i]);u.push_back(r.u[i]);}cells=std::move(next);r.x=std::move(x);r.u=std::move(u);
}
inline std::array<double,3> adaptiveQ(double left,double center,double right,double dt,double a,double b,double c){
 double hL=sub(center,left),hR=sub(right,center),H=add(hL,hR);if(!(hL>0&&hR>0&&H>0))throw std::runtime_error("oracle geometry");
 double vL=div(dt,hL),vR=div(dt,hR),rL=div(vL,H),rR=div(vR,H),rD=div(vL,hR),zL=div(hR,H),zR=div(hL,H),sL=mul(vL,zL),sR=mul(vR,zR),sD=sub(vL,vR);
 double arL=mul(a,rL),arD=mul(a,rD),arR=mul(a,rR),bsL=mul(b,sL),bsD=mul(b,sD),bsR=mul(b,sR),cdt=mul(c,dt),dL=mul(2,arL),dD=mul(-2,arD),dR=mul(2,arR),qL=sub(dL,bsL),qD0=add(dD,bsD),qD=add(qD0,cdt),qR=add(dR,bsR);return {qL,qD,qR};
}
template<class P> inline void adaptiveStep(ReferenceResult& r,P const& p,double oldt,double newt,double dt,double theta){std::size_t n=r.x.size()-2;std::vector<double> l(n-1),d(n),u(n-1),rhs(n);double bl=checked(p.boundaryL(newt,r.x.front())),br=checked(p.boundaryR(newt,r.x.back()));for(std::size_t j=0;j<n;++j){std::size_t i=j+1;double x=r.x[i];double a=mean(checked(p.diffusion(oldt,x)),checked(p.diffusion(newt,x))),b=mean(checked(p.advection(oldt,x)),checked(p.advection(newt,x))),c=mean(checked(p.reaction(oldt,x)),checked(p.reaction(newt,x)));auto q=adaptiveQ(r.x[i-1],x,r.x[i+1],dt,a,b,c);double omega=sub(1,theta),al=checked(-mul(theta,q[0])),ad=sub(1,mul(theta,q[1])),ar=checked(-mul(theta,q[2]));double oldL=mul(mul(omega,q[0]),r.u[i-1]),oldD=mul(add(1,mul(omega,q[1])),r.u[i]),oldR=mul(mul(omega,q[2]),r.u[i+1]);double oldf=theta==1?0:mul(omega,checked(p.source(oldt,x))),newf=mul(theta,checked(p.source(newt,x))),source=mul(add(oldf,newf),dt);double y=add(add(add(oldL,oldD),oldR),source);if(j==0)y=sub(y,mul(al,bl));else l[j-1]=al;if(j+1==n)y=sub(y,mul(ar,br));else u[j]=ar;d[j]=ad;rhs[j]=y;}auto interior=thomas(l,d,u,rhs);r.u.front()=bl;r.u.back()=br;for(std::size_t j=0;j<n;++j)r.u[j+1]=interior[j];}
template<class G,class P> inline ReferenceResult reference(G const& g,P const& p,double theta,PDE::AMROptions const& o){ReferenceResult r;std::vector<Leaf> cells;for(std::size_t i=0;i<g.nx();++i){r.x.push_back(g.x(i));r.u.push_back(i==0?checked(p.boundaryL(g.t(0),g.x(i))):i+1==g.nx()?checked(p.boundaryR(g.t(0),g.x(i))):checked(p.initial(g.t(0),g.x(i))));if(i)cells.push_back({g.x(i-1),g.x(i),i-1,0,0});}adapt(r,cells,p,o,0,g.t(0));for(std::size_t k=1;k<=g.nt();++k){adaptiveStep(r,p,g.t(k-1),g.t(k),g.dt(),theta);if(k<g.nt())adapt(r,cells,p,o,k,g.t(k));}return r;}
inline void compare(PDE::Solution1D const& actual,ReferenceResult const& expected){ASSERT_EQ(actual.x,expected.x);ASSERT_EQ(actual.values.size(),expected.u.size());for(std::size_t i=0;i<expected.u.size();++i){ASSERT_TRUE(std::isfinite(actual.values[i]));double tolerance=256*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(expected.u[i]));EXPECT_NEAR(actual.values[i],expected.u[i],tolerance)<<"node="<<i;}EXPECT_EQ(actual.refinement_limited,expected.limited);ASSERT_EQ(actual.events.size(),expected.events.size());for(std::size_t j=0;j<expected.events.size();++j){auto const& a=actual.events[j];auto const& e=expected.events[j];EXPECT_EQ(a.step,e.step);EXPECT_DOUBLE_EQ(a.time,e.time);EXPECT_EQ(a.action,e.action);EXPECT_DOUBLE_EQ(a.left,e.left);EXPECT_DOUBLE_EQ(a.right,e.right);}}
}
#endif
